<?php\ndeclare(strict_types=1);\n\nnamespace Acme\\Pricing\\Unified;\n\n/**\n * Unified basket pricing — rate and type are now parameters\n */\nclass BasketPricing\n{\n    public function calculatePrice(float $amount, float $rate, string $type): array\n    {\n        $discount = $amount * $rate;\n        $discounted = $amount - $discount;\n        $tax = $discounted * 0.08;\n        $total = $discounted + $tax;\n\n        return [\n            'original' => $amount,\n            'discount' => $discount,\n            'discounted' => $discounted,\n            'tax' => $tax,\n            'total' => $total,\n            'type' => $type,\n        ];\n    }\n}
